FUNCTION UNDER TEST:
Name: buffer_prepend
Signature: int buffer_prepend(buffer_t *self, char *str)
Description: /**
 * @brief Prepends a string to the beginning of a buffer.
 *
 * Inserts the contents of the given string at the start of the buffer,
 * shifting existing data forward as needed. Resizes the buffer if there
 * is not enough space to accommodate the new data.
 *
 * @param self Pointer to the buffer to modify. Must not be NULL and must
 *             reference a valid, initialized buffer_t structure.
 * @param str Null-terminated string to prepend. Must not be NULL.
 *
 * @return Returns 0 on success, or -1 if memory allocation fails during resizing.
 *
 * @note The buffer is modified in place. Existing data is shifted forward.
 * @note Error is signaled by return value; no errno is set.
 *
 * @see buffer_resize
 */
Dependencies: buffer_resize

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_prepend
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Forward declarations for dependency functions
int
buffer_resize(buffer_t *self, size_t n);

// Target function implementation
int
buffer_prepend(buffer_t *self, char *str) {
  size_t len = strlen(str);
  size_t prev = strlen(self->data);
  size_t needed = len + prev;

  // enough space
  if (self->len > needed) goto move;

  // resize
  int ret = buffer_resize(self, needed);
  if (-1 == ret) return -1;

  // move
  move:
  memmove(self->data + len, self->data, len + 1);
  memcpy(self->data, str, len);

  return 0;
}

```

